// Extract incoming filters from Webhook Trigger
let triggerInput = {};
try {
  triggerInput = $('Webhook Trigger').first().json.body || {};
} catch (e) {
  triggerInput = {};
}

const requestedProduct = (triggerInput.productTag || triggerInput.productId || 'all').toLowerCase();
const requestedEnv = (triggerInput.environment || 'production').toLowerCase();

// Extract raw MongoDB FOCUS documents from MongoDB Node
let docs = [];
if (Array.isArray($json)) {
  docs = $json;
} else if ($json.documents && Array.isArray($json.documents)) {
  docs = $json.documents;
} else if ($json.data && Array.isArray($json.data)) {
  docs = $json.data;
} else {
  try {
    const mongoNode = $('Query MongoDB Documents').first().json;
    docs = mongoNode.documents || mongoNode.data || (Array.isArray(mongoNode) ? mongoNode : []);
  } catch (e) {
    docs = [];
  }
}

// 1. Process Keys directly from MongoDB documents
const firstWithMeta = docs.find(d => d.keysList && Array.isArray(d.keysList) && d.keysList.length > 0);

const rawKeysList = firstWithMeta?.keysList || docs.map((d, idx) => ({
  keyId: d.resourceId || `key_${idx + 1}`,
  name: d.SubServiceName || (d.service ? d.service.replace('OpenRouter - ', '') : `Key ${idx + 1}`),
  label: d.tags?.KeyLabel || '',
  usage: Number(d.amortizedCost || d.unblendedCost || 0),
  limit: typeof d.limit === 'number' ? d.limit : (typeof d.creditLimit === 'number' ? d.creditLimit : null),
  remaining: typeof d.remaining === 'number' ? d.remaining : (typeof d.remainingBalance === 'number' ? d.remainingBalance : null),
  createdAt: d.ChargePeriodStart || d.date || d.createdAt,
  usageDaily: Number(d.usageDaily || 0),
  usageWeekly: Number(d.usageWeekly || 0),
  usageMonthly: Number(d.usageMonthly || 0),
  environment: (d.tags?.Environment || d.environment || 'production').toLowerCase(),
  productTag: d.tags?.Project || d.productTag || 'SHARED_GATEWAY'
}));

// 2. Filter Keys if a specific product or environment is requested
const filteredKeys = rawKeysList.filter(k => {
  if (requestedProduct !== 'all' && requestedProduct !== 'shared_gateway') {
    if (k.productTag && k.productTag.toLowerCase() !== requestedProduct) return false;
  }
  if (requestedEnv !== 'all') {
    if (k.environment && k.environment.toLowerCase() !== requestedEnv) return false;
  }
  return true;
});

const activeKeys = filteredKeys.length > 0 ? filteredKeys : rawKeysList;

// 3. Compute Unit Economics directly from exact MongoDB records
const totalSpend = Number(activeKeys.reduce((acc, k) => acc + (Number(k.usage) || 0), 0).toFixed(4));
const totalMonthly = Number(activeKeys.reduce((acc, k) => acc + (Number(k.usageMonthly) || 0), 0).toFixed(4));
const totalWeekly = Number(activeKeys.reduce((acc, k) => acc + (Number(k.usageWeekly) || 0), 0).toFixed(4));
const totalDaily = Number(activeKeys.reduce((acc, k) => acc + (Number(k.usageDaily) || 0), 0).toFixed(4));

const creditLimit = typeof firstWithMeta?.creditLimit === 'number'
  ? firstWithMeta.creditLimit
  : Number(activeKeys.reduce((acc, k) => acc + (Number(k.limit) || 0), 0).toFixed(2));

const remainingBalance = typeof firstWithMeta?.remainingBalance === 'number'
  ? firstWithMeta.remainingBalance
  : Number(activeKeys.reduce((acc, k) => acc + (Number(k.remaining) || 0), 0).toFixed(2));

const sortedKeys = [...activeKeys].sort((a, b) => (Number(b.usage) || 0) - (Number(a.usage) || 0));
const topKeyItem = sortedKeys[0] || null;

// 4. Product Allocation Mapping - Computed dynamically from real key productTags
const productAllocation = {};
for (const k of activeKeys) {
  let pTag = (k.productTag || 'shared').toLowerCase();
  // Detect product category from tag or key name
  if (pTag.includes('dragon') || k.name.toUpperCase().startsWith('DS') || k.name.toLowerCase().includes('chatbot')) {
    pTag = 'dragon';
  } else if (pTag.includes('okrian') || k.name.toLowerCase().includes('dev')) {
    pTag = 'okrian';
  } else if (pTag.includes('workbench') || k.name.toLowerCase().includes('coe') || k.name.toLowerCase().includes('migration')) {
    pTag = 'workbench';
  } else {
    pTag = 'shared';
  }
  productAllocation[pTag] = Number(((productAllocation[pTag] || 0) + (Number(k.usage) || 0)).toFixed(4));
}
productAllocation.total = totalSpend;

// 5. Model / Key Breakdown with Exact Percentage Share
const topModelsBySpend = sortedKeys.map(k => ({
  name: k.name,
  provider: 'OpenRouter',
  label: k.label,
  cost: Number(k.usage || 0),
  share: totalSpend > 0 ? Number(((Number(k.usage || 0) / totalSpend) * 100).toFixed(1)) : 0,
  dailyCost: Number(k.usageDaily || 0),
  weeklyCost: Number(k.usageWeekly || 0),
  monthlyCost: Number(k.usageMonthly || 0),
  limit: k.limit,
  remaining: k.remaining,
  createdAt: k.createdAt
}));

// 6. Date-wise Telemetry Table from exact documents
const dateWiseTelemetry = activeKeys.map((k, idx) => ({
  id: `telemetry_${k.keyId || idx + 1}`,
  date: (k.createdAt || '').split('T')[0] || new Date().toISOString().split('T')[0],
  keyName: k.name,
  keyLabel: k.label,
  keyCreatedAt: k.createdAt,
  app: k.productTag || 'SHARED_GATEWAY',
  model: k.name,
  cost: Number(k.usage || 0),
  dailyCost: Number(k.usageDaily || 0),
  weeklyCost: Number(k.usageWeekly || 0),
  monthlyCost: Number(k.usageMonthly || 0),
  environment: k.environment || 'production'
}));

return {
  success: true,
  connectionId: docs[0]?.connectionId || 'Production OpenRouter',
  connectionName: docs[0]?.accountName || 'Production OpenRouter',
  productTag: requestedProduct,
  environment: requestedEnv,
  totalUsage: totalSpend,
  monthlySpend: totalMonthly,
  weeklySpend: totalWeekly,
  dailySpend: totalDaily,
  creditLimit: creditLimit,
  remainingBalance: remainingBalance,
  topSpendingKey: {
    name: topKeyItem?.name || 'Active Key',
    cost: topKeyItem ? Number(topKeyItem.usage || 0) : 0,
    share: totalSpend > 0 && topKeyItem ? Number(((Number(topKeyItem.usage || 0) / totalSpend) * 100).toFixed(1)) : 0
  },
  recordsIngested: activeKeys.length,
  keysList: activeKeys,
  topModelsBySpend: topModelsBySpend,
  dateWiseTelemetry: dateWiseTelemetry,
  productAllocation: productAllocation,
  lastSyncedAt: docs[0]?.updatedAt || new Date().toISOString()
};
